{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Invest — Pricing & Bundles | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Transparent pricing for private sessions, small-group gatherings, and bundles with short-course resources.">
  <style>
    :root{--bg:#f6efe6;--accent:#7a4b2a;--muted:#6f5e51;--card:#fff}
    body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial;background:linear-gradient(180deg,#f8f0e4,#efe7da);color:var(--muted)}
    .frame{max-width:980px;margin:18px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .pricing-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:18px}
    .card{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 8px 30px rgba(90,70,50,0.06)}
    .plan-title{font-weight:700;color:var(--accent)}
    .price{font-size:22px;font-weight:700;margin-top:8px}
    .note{font-size:13px;color:#8a7a6e;margin-top:8px}
    .cta{margin-top:12px}
    .cta a{display:inline-block;padding:8px 12px;border-radius:10px;text-decoration:none}
    .primary{background:var(--accent);color:#fff}
    .muted{color:#8a7a6e}
    @media(max-width:980px){.pricing-grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="frame">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#b67a4b);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700">S</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:#8a7a6e">Honest pricing for steady returns in attention and rest</div>
        </div>
      </div>
      <nav>
        <a href="/">Home</a>
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Sessions</a>
        <a href="/book.html">Book</a>
      </nav>
    </header>

    <main style="margin-top:18px">
      <h1 style="color:var(--accent)">Investments & Bundles</h1>
      <p class="muted">Choose single sessions, a short series, or flexible credits to use across offerings.</p>

      <section class="pricing-grid">
        <div class="card">
          <div class="plan-title">Single Grounding</div>
          <div class="price">$95</div>
          <div class="note">A focused 45-minute private session for immediate re-orientation.</div>
          <div class="cta"><a class="primary" href="{{PRIMARY_CTA_URL}}">Book now</a></div>
        </div>

        <div class="card">
          <div class="plan-title">Aligning Session</div>
          <div class="price">$165</div>
          <div class="note">75–90 minute deep session with a short integration plan.</div>
          <div class="cta"><a class="primary" href="{{PRIMARY_CTA_URL}}">Reserve</a></div>
        </div>

        <div class="card">
          <div class="plan-title">Home Calm — Mobile</div>
          <div class="price">$220+</div>
          <div class="note">In-home setup and session. Travel included within {{CITY}} area — contact for exact quote.</div>
          <div class="cta"><a class="primary" href="{{PRIMARY_CTA_URL}}">Request visit</a></div>
        </div>
      </section>

      <section style="margin-top:18px;display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap">
        <div class="card" style="flex:1;min-width:260px">
          <h3 style="color:var(--accent)">Short series — Gentle Return (3)</h3>
          <div class="muted">Three aligned sessions spaced 1–3 weeks apart. Structured guidance & a follow-up digital pack.</div>
          <div style="font-weight:700;margin-top:8px">Package price: $440</div>
          <div style="margin-top:10px" class="note">Includes a 15-minute follow-up check-in after the third session and a downloadable integration guide.</div>
          <div style="margin-top:10px"><a class="primary" href="{{PRIMARY_CTA_URL}}">Start the series</a></div>
        </div>

        <div class="card" style="width:300px">
          <h4 style="margin-top:0;color:var(--accent)">Credits — Flexible</h4>
          <div class="muted">Buy a block of credits and use them for gatherings or private sessions within six months.</div>
          <div style="margin-top:8px;font-weight:700">5 Credits — $420</div>
          <div class="muted" style="margin-top:8px">Each credit can be applied toward studio gatherings or private time.</div>
          <div style="margin-top:10px"><a class="primary" href="{{PRIMARY_CTA_URL}}">Purchase credits</a></div>
        </div>
      </section>

      <section style="margin-top:18px" class="card">
        <h3 style="margin-top:0;color:var(--accent)">Fairness & small print</h3>
        <p class="muted">Sessions are reserved with a nominal hold; full confirmations and any cancellation policy are handled in booking. Prices quoted here are subject to change for special events or off-site travel. For accessibility accommodations or sliding-scale requests, email {{EMAIL}}.</p>

        <div style="margin-top:12px;display:flex;gap:8px">
          <button class="primary" id="openTryPricing">Try a short practice</button>
          <a href="/book.html" style="padding:8px 12px;border-radius:8px;background:#e9d6c9;color:var(--accent);text-decoration:none">Book a consult</a>
        </div>
      </section>
    </main>

    <footer style="margin-top:18px;color:#8a7a6e;font-size:13px">Questions: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></footer>
  </div>

  <!-- Practice modal similar to other pages but with slightly different script flow -->
  <div id="pricingPractice" style="display:none;position:fixed;inset:0;background:rgba(12,10,8,0.6);align-items:center;justify-content:center;padding:20px">
    <div role="dialog" aria-modal="true" style="max-width:560px;width:100%;background:#fff;padding:18px;border-radius:12px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:700;color:var(--accent)">Three-minute anchor</div>
        <button id="closePricingPractice" style="background:transparent;border:0;font-size:18px">✕</button>
      </div>
      <div id="pricingPracticeContent" style="margin-top:12px">
        <div style="font-size:15px">A guided, timed breathing & journaling combo — follow the prompts below.</div>
        <div id="pricingTimer" style="font-weight:700;font-size:28px;margin-top:12px;color:#444">Ready</div>
        <div style="margin-top:12px;display:flex;gap:8px"><button id="startPricingPractice" class="primary">Begin</button><button id="stopPricingPractice" class="muted" style="background:#eee;border:0;padding:8px;border-radius:8px">Stop</button></div>
      </div>
    </div>
  </div>

  <script>
    (function(){
      const open = document.getElementById('openPricingPractice');
      const modal = document.getElementById('pricingPractice');
      const close = document.getElementById('closePricingPractice');
      const start = document.getElementById('startPricingPractice');
      const stop = document.getElementById('stopPricingPractice');
      const timer = document.getElementById('pricingTimer');
      let tId=null; let phase=0; let rounds=0;
      open && open.addEventListener('click', ()=>{ modal.style.display='flex'; timer.textContent='Ready'; });
      close && close.addEventListener('click', ()=>{ modal.style.display='none'; stopPractice(); });
      start && start.addEventListener('click', startPractice);
      stop && stop.addEventListener('click', ()=>{ stopPractice(); modal.style.display='none'; });

      function startPractice(){ if(tId) return; phase=0; rounds=0; timer.textContent='Inhale 4'; tId = setInterval(()=>{
        if(phase===0){ timer.textContent='Inhale — 4'; setTimeout(()=>{ phase=1; },4000); }
        else if(phase===1){ timer.textContent='Exhale — 6'; setTimeout(()=>{ phase=0; rounds++; if(rounds>=3){ stopPractice(); timer.textContent='Finished — sit for a moment.'; } },6000); }
      },1000); }
      function stopPractice(){ if(tId) clearInterval(tId); tId=null; }
    })();
  </script>
</body>
</html>"} 
